import{z as P,x as o,o as t,c as i,q as A,j as l,D as e,d as s,s as B,S as n,b as E}from"./chunks/framework.C8m1ZpeB.js";const M=JSON.parse('{"title":"RSTP / MSTP","description":"","frontmatter":{"title":"RSTP / MSTP","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/rstp-mstp.md","filePath":"cs/rstp-mstp.md","lastUpdated":1791063341000}'),p={name:"cs/rstp-mstp.md"};function T(d,a,S,C,m,D){const r=o("Mermaid");return t(),i("div",null,[a[2]||(a[2]=A('<h1 id="rstp-mstp" tabindex="-1">RSTP / MSTP <a class="header-anchor" href="#rstp-mstp" aria-label="Permalink to &quot;RSTP / MSTP&quot;">​</a></h1><div class="epigraph"><p>RSTP 用提议/同意握手把端口从阻塞拉到转发，秒级收敛；MSTP 让多棵树共享区域，按 VLAN 组走不同根。</p><footer>—— 据 IEEE 802.1w RSTP；IEEE 802.1s / 802.1Q MSTP；Perlman 生成树原文对照整理</footer></div><p>主干<a href="/cs/spanning-tree">生成树</a> 已钉根桥与阻塞。<a href="/cs/lldp">上一课</a> 不改拓扑。缺口是<strong>收敛太慢与一棵树不够</strong>：经典 802.1D 计时器以 30–50 s 计；RSTP 用握手；MSTP 把 VLAN 映射到多实例，避免所有 VLAN 共用一条阻塞。本课不把 MAC 学习算法写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>接入口接主机，不必等转发延迟：edge 口可直接转发，BPDU 守卫防环。点到点口用 proposal/agreement 同步子树。MSTP：一个区域里多棵 IST/CIST 与 MSTI，VLAN 映射表必须全区一致，否则环或黑洞。这不是 IP 的 ECMP，仍是二层无环。<span class="marginnote">数字实例：经典 STP 里一个口要等「侦听 15 秒 + 学习 15 秒」才敢转发，链路故障切换最长可拖到 50 秒；RSTP 用握手把这个过程压到几百毫秒——差出两个数量级，这正是它存在的理由。</span></p><p>不要把 RSTP 的「秒」当成应用 SLA：还有 MAC 刷新与上层超时。</p><p><span class="marginnote">802.1Q 已并入 RSTP/MSTP。PVST+ 是厂商对照：每 VLAN 一棵，开销大。本课以标准 MSTP 为主。</span></p><h3 id="秒级仍是二层树" tabindex="-1">秒级仍是二层树 <a class="header-anchor" href="#秒级仍是二层树" aria-label="Permalink to &quot;秒级仍是二层树&quot;">​</a></h3><p>握手替代长转发延迟，不是 IP ECMP。MSTP 映射必须全区一致，否则环或黑洞。边缘口快转发仍要 BPDU 守卫。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照：STP 计时器 vs RSTP 握手 vs MSTP 实例。画：区域边界用 CIST 与外网相连。根优先级仍决定哪台转发多。LACP 逻辑口作为一条 RSTP 边。<span class="marginnote">术语翻译：MSTI（多生成树实例）就是用「把几百个 VLAN 按流量特征分成几组、每组跑一棵自己的树」的手段来做「不同 VLAN 走不同的路、别全挤在同一条阻塞链上」的事——注意树的数量是个位数，不是 VLAN 数。</span></p>',11)),(t(),l(n,null,{default:e(()=>[B(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20EDGE%5B%22%E8%BE%B9%E7%BC%98%E5%8F%A3%3A%20%E7%AB%8B%E5%8D%B3%E8%BD%AC%E5%8F%91%22%5D%20--%3E%20PP%5B%22%E7%82%B9%E5%88%B0%E7%82%B9%E6%8F%A1%E6%89%8B%22%5D%0A%20%20PP%20--%3E%20FWD%5B%22%E5%90%8C%E6%AD%A5%E5%90%8E%E8%BD%AC%E5%8F%91%22%5D%0A%20%20VLAN%5B%22VLAN%20%E5%88%86%E7%BB%84%22%5D%20--%3E%20MSTI%5B%22%E5%A4%9A%E5%AE%9E%E4%BE%8B%E6%A0%91%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[s("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"LLDP 名字帮你确认插线；RSTP 决定哪些口真正发数据。PFC 暂停不替代阻塞：阻塞是拓扑，暂停是队列。主干 VLAN 课的广播域在 MSTP 里可以有不同的转发树，减少绕路。",-1)),a[5]||(a[5]=E("p",null,[s("TCN：拓扑变仍要冲刷 MAC，否则帧跟旧口走。后课 MAC 学习会收回这句。"),E("span",{class:"marginnote"},"常见误区：初学者容易以为「RSTP 秒级收敛就等于业务无感」——端口恢复转发只是第一步；MAC 表还指着旧口时帧会继续走错路，必须靠拓扑变更通告冲刷 MAC 表，上层 TCP 的超时也可能早已被触发。")],-1)),(t(),l(n,null,{default:e(()=>[B(r,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20UP%5B%22%E9%93%BE%E8%B7%AF%E8%B5%B7%E6%9D%A5%22%5D%20--%3E%20TYPE%7B%22%E8%BF%99%E6%98%AF%E4%BB%80%E4%B9%88%E5%8F%A3%EF%BC%9F%22%7D%0A%20%20TYPE%20--%20%22%E8%BE%B9%E7%BC%98%E5%8F%A3%20%E6%8E%A5%E4%B8%BB%E6%9C%BA%22%20--%3E%20FWD1%5B%22%E7%9B%B4%E6%8E%A5%E8%BF%9B%E8%BD%AC%E5%8F%91%20%E5%B9%B6%E6%8C%82%20BPDU%20%E5%AE%88%E5%8D%AB%22%5D%0A%20%20TYPE%20--%20%22%E7%82%B9%E5%88%B0%E7%82%B9%E5%8F%A3%20%E6%8E%A5%E4%BA%A4%E6%8D%A2%E6%9C%BA%22%20--%3E%20PROP%5B%22%E5%8F%91%E5%87%BA%20Proposal%20%E6%8F%90%E8%AE%AE%22%5D%0A%20%20PROP%20--%3E%20AGREE%7B%22%E5%AF%B9%E7%AB%AF%E5%90%8C%E6%84%8F%E4%B8%94%E4%B8%8B%E6%B8%B8%E5%85%A8%E5%90%8C%E6%AD%A5%EF%BC%9F%22%7D%0A%20%20AGREE%20--%20%22%E6%98%AF%22%20--%3E%20FWD2%5B%22%E8%BF%9B%E5%85%A5%E8%BD%AC%E5%8F%91%22%5D%0A%20%20AGREE%20--%20%22%E5%90%A6%22%20--%3E%20DISC%5B%22%E5%81%9C%E5%9C%A8%E4%B8%A2%E5%BC%83%E6%80%81%20%E7%AD%89%E9%87%8D%E8%AF%95%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[s(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=A('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 TRILL/SPB 的链路状态二层。MAC 学习与洪泛是下一课。后课默认：当代二层环保护以 RSTP/MSTP 为默认词汇。</p><p>数据中心后课常用 Clos + L3，少跑大二层；那是后话，不在本课废除生成树。</p><p>下一课<a href="/cs/mac-learning">MAC 学习与洪泛</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>RSTP 握手替代长转发延迟；边缘口快。</li><li>MSTP 按 VLAN 组多树，映射必须一致。</li><li>仍是无环二层，不是路由 ECMP。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：IEEE 802.1w/s；Perlman, 1985。</li></ul>',6))])}const c=P(p,[["render",T]]);export{M as __pageData,c as default};
